    mod = inputs['mod']

    def matrix_mult(A, B, m):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % m
        return C

    def matrix_power(M, exp, m):
        n = len(M)
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, m)
            base = matrix_mult(base, base, m)
            exp //= 2

        return result

    result_matrix = matrix_power(matrix, power, mod)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)

    return float(total % mod)

